resources.content:
body {
  font-family: Arial, sans-serif;
  background-color: #f3f5f1;
  color: #243b35;
  max-width: 900px;
  margin: 0 auto;
  padding: 24px;
  line-height: 1.6;
}
header { border-bottom: 2px solid #c9d4ca; padding-bottom: 20px; }
.marque { font-weight: bold; letter-spacing: 2px; color: #185b49; }
nav a { display: inline-block; margin-right: 24px; }
a { color: #185b49; text-underline-offset: 4px; }
main { padding-top: 30px; }
h1 { font-size: 36px; line-height: 1.2; max-width: 650px; }
h2 { font-size: 22px; line-height: 1.3; }
.rubrique { font-size: 12px; font-weight: bold; letter-spacing: 1px; color: #52665b; }
section { background-color: white; padding: 24px; margin: 24px 0; border-radius: 8px; }
.encadre-information {
  background-color: #fff1cb;
  border-left: 6px solid #9b6900;
  padding: 24px;
}
button {
  font: inherit;
  font-weight: bold;
  background-color: #185b49;
  color: white;
  border: 2px solid #185b49;
  border-radius: 5px;
  padding: 10px 16px;
  cursor: pointer;
}
button:hover { background-color: #113f33; }
a:focus-visible, button:focus-visible { outline: 3px solid #9b6900; outline-offset: 4px; }
footer { border-top: 1px solid #c9d4ca; margin-top: 36px; padding: 20px 0; font-size: 13px; }

