const boutonHoraires = document.querySelector("#bouton-horaires");
const horaires = document.querySelector("#horaire");

boutonHoraires.addEventListener("click", () => {
  horaires.textContent = "Le centre de services est ouvert du lundi au vendredi, de 8 h à 17 h.";
});

const boutonConseil = document.querySelector("#bouton-conseil");
const conseil = document.querySelector("#horaires");

boutonConseil.addEventListener("click", () => {
  conseil.textContent = "Indiquez le message d’erreur exact et les étapes pour reproduire le problème.";
});

const boutonProcedure = document.querySelector("#bouton-procedure");
const procedure = document.querySelector("#procedure");

boutonProcedure.addEventListener("click", () => {
  procedure.textContent = "Votre demande a été transmise à la DSIIR. Un technicien vous contactera.";
});

